import struct, sys

LOSS={1:'hs',2:'ns',3:'softmax',4:'ova'}
MODEL={1:'cbow',2:'sg',3:'sup'}

class R:
    def __init__(self,b): self.b=b; self.p=0
    def i32(self):
        v=struct.unpack_from('<i',self.b,self.p)[0]; self.p+=4; return v
    def i64(self):
        v=struct.unpack_from('<q',self.b,self.p)[0]; self.p+=8; return v
    def u8(self):
        v=self.b[self.p]; self.p+=1; return v
    def f32(self):
        v=struct.unpack_from('<f',self.b,self.p)[0]; self.p+=4; return v
    def cstr(self):
        e=self.b.index(0,self.p); s=self.b[self.p:e].decode('utf-8',errors='replace'); self.p=e+1; return s

def parse(path, verbose=True):
    b=open(path,'rb').read()
    r=R(b)
    magic=r.i32(); ver=r.i32()
    out={'magic':magic,'version':ver}
    args={}
    for k in ['dim','ws','epoch','minCount','neg','wordNgrams']:
        args[k]=r.i32()
    args['loss']=LOSS.get(r.i32())
    args['model']=MODEL.get(r.i32())
    for k in ['bucket','minn','maxn','lrUpdateRate']:
        args[k]=r.i32()
    args['t']=struct.unpack_from('<d',r.b,r.p)[0]; r.p+=8
    out['args']=args
    size=r.i32(); nwords=r.i32(); nlabels=r.i32(); ntokens=r.i64(); pruneidx_size=r.i64()
    out['dict']={'size':size,'nwords':nwords,'nlabels':nlabels,'ntokens':ntokens,'pruneidx_size':pruneidx_size}
    words=[]
    for i in range(size):
        w=r.cstr(); c=r.i64(); t=r.u8()
        words.append((w,c,t))
    out['words']=words
    pruneidx=[]
    if pruneidx_size>0:
        for i in range(pruneidx_size):
            a=r.i32(); bb=r.i32(); pruneidx.append((a,bb))
    out['pruneidx']=pruneidx
    quant=r.u8()
    out['quant']=quant
    def readdense():
        m=r.i64(); n=r.i64()
        data=struct.unpack_from('<%df'%(m*n), r.b, r.p); r.p+=4*m*n
        return m,n,data
    if quant==0:
        m,n,d=readdense(); out['input']=(m,n,d)
    else:
        out['input']='QUANT@%d'%r.p
        return out,r
    qout=r.u8(); out['qout']=qout
    m,n,d=readdense(); out['output']=(m,n,d)
    out['pos']=r.p; out['filesize']=len(b)
    return out,r

if __name__=='__main__':
    o,r=parse(sys.argv[1])
    print('magic',o['magic'],'ver',o['version'])
    print('args',o['args'])
    print('dict',o['dict'])
    print('words',o['words'][:12], '...' if len(o['words'])>12 else '')
    print('pruneidx',o['pruneidx'][:5])
    print('quant',o['quant'],'qout',o.get('qout'))
    if isinstance(o['input'],tuple):
        print('input',o['input'][0],o['input'][1], o['input'][2][:8])
    if 'output' in o: print('output',o['output'][0],o['output'][1],o['output'][2][:8])
    print('endpos',o.get('pos'),'filesize',o.get('filesize'))
